import{_ as t,c as a,o as r,ag as i}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"Coverage, source notes and certification","description":"","frontmatter":{},"headers":[],"relativePath":"aws/coverage-and-sources.md","filePath":"aws/coverage-and-sources.md"}'),n={name:"aws/coverage-and-sources.md"};function o(s,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="coverage-source-notes-and-certification" tabindex="-1">Coverage, source notes and certification <a class="header-anchor" href="#coverage-source-notes-and-certification" aria-label="Permalink to “Coverage, source notes and certification”">​</a></h1><p>These notes combine the supplied CloudX course extracts and slide decks into an ordered explanation. They are a synthesis with additional context, not a verbatim mirror or a record of completed practical work.</p><h2 id="how-the-two-courses-contribute" tabindex="-1">How the two courses contribute <a class="header-anchor" href="#how-the-two-courses-contribute" aria-label="Permalink to “How the two courses contribute”">​</a></h2><table tabindex="0"><thead><tr><th>Source area</th><th>Canonical chapter in this path</th></tr></thead><tbody><tr><td>Cloud introduction and AWS essentials</td><td><a href="./beginner-guide.html">Beginner guide</a>, <a href="./account-and-tools.html">account and tools</a></td></tr><tr><td>IAM, credentials and policies</td><td><a href="./iam-and-security.html">IAM and security</a></td></tr><tr><td>Frontend deployment, S3 and CloudFront</td><td><a href="./storage-and-frontend.html">Storage and frontend</a></td></tr><tr><td>CDK examples and CloudFormation theory</td><td><a href="./infrastructure-as-code.html">Infrastructure as code</a></td></tr><tr><td>Lambda, API Gateway and serverless</td><td><a href="./serverless-and-apis.html">Serverless and APIs</a></td></tr><tr><td>DynamoDB, RDS, SQL and NestJS/ORM</td><td><a href="./databases.html">Databases</a></td></tr><tr><td>S3 file processing</td><td><a href="./file-imports.html">File imports</a></td></tr><tr><td>Async communication, SQS and SNS</td><td><a href="./messaging.html">Messaging</a></td></tr><tr><td>Authorization and Cognito</td><td><a href="./authentication.html">Authentication</a></td></tr><tr><td>EC2, Auto Scaling and load balancing</td><td><a href="./compute-and-scaling.html">Compute</a></td></tr><tr><td>VPC, DNS and network connectivity</td><td><a href="./networking.html">Networking</a></td></tr><tr><td>Developer tools, monitoring and cleanup</td><td><a href="./delivery-and-operations.html">Delivery and operations</a></td></tr><tr><td>AI tools and services</td><td><a href="./ai-services.html">AI services</a></td></tr></tbody></table><p>The Practitioner material supplies application-building continuity. The Associate material broadens service and infrastructure understanding. Networking, compute, messaging and IAM contain deeper concepts even where a chapter is titled “Introduction.” Optional linked reading remains further depth, not proof that the course teaches every linked subject comprehensively.</p><p>The supplied S3 introduction, S3/CloudFront and database PDFs inform the storage and database explanations. Their diagrams and examples have been summarized rather than copied wholesale. Course assignments, grading criteria and practical lab deliverables are organized separately in the <a href="./../practice/aws/">AWS homework path</a>. Every supplied optional/bonus task is required locally; original grading boundaries remain explicit.</p><h2 id="corrections-and-modernization" tabindex="-1">Corrections and modernization <a class="header-anchor" href="#corrections-and-modernization" aria-label="Permalink to “Corrections and modernization”">​</a></h2><table tabindex="0"><thead><tr><th>Older or misleading source detail</th><th>Treatment in these notes</th></tr></thead><tbody><tr><td>S3 overwrites/deletes described as eventually consistent</td><td>Explain strong object read-after-write consistency separately from CDN caching</td></tr><tr><td>OAI used as the frontend default</td><td>Explain OAC for a private S3 origin and its website-endpoint limitation</td></tr><tr><td>IAM PassRole conflated with AssumeRole</td><td>Distinguish service role assignment from creating a role session</td></tr><tr><td>Long-lived administrator keys as the primary setup</td><td>Prefer temporary credentials and separate deployment/workload identities</td></tr><tr><td>FIFO described as exactly-once business execution</td><td>Explain deduplication boundaries and duplicate-safe side effects</td></tr><tr><td>Queue handler reads only the first record</td><td>Explain all-record processing and the partial batch failure contract</td></tr><tr><td>SDK v2 and old runtime examples</td><td>Use SDK v3 as the development reference; verify runtime support before deployment</td></tr><tr><td>TypeScript files copied as Lambda code</td><td>Explain required compilation/bundling and handler alignment</td></tr><tr><td>Basic authentication described as encrypted/unencrypted without transport context</td><td>Separate reversible Base64 encoding from HTTPS encryption</td></tr><tr><td>API keys equated with OAuth client credentials</td><td>Explain their different purposes</td></tr><tr><td>Disabling database certificate verification to fix connectivity</td><td>Diagnose the failure and use proper CA verification</td></tr><tr><td>Fixed prices, quotas and Free Tier assumptions</td><td>Link current documentation rather than preserve historical numbers</td></tr><tr><td>Historical service names and screenshots</td><td>Prefer current concepts and service references over menu positions</td></tr></tbody></table><p>Official references for key corrected behaviors were checked on <strong>28 October 2026</strong>. This is not a guarantee that every historical source link, screenshot or feature remains current. No AWS resources were deployed or live-account behavior tested while writing these notes.</p><h2 id="expected-proficiency" tabindex="-1">Expected proficiency <a class="header-anchor" href="#expected-proficiency" aria-label="Permalink to “Expected proficiency”">​</a></h2><p>A learner who only reads the chapters gains vocabulary and conceptual familiarity. An existing JavaScript developer who independently applies and explains the patterns can develop strong junior AWS application-development skills. Medior readiness additionally requires sound choices under incomplete requirements, unfamiliar failure investigation and ownership of releases and recovery.</p><p>These labels are contextual, not a universal AWS grading scale. A medior backend developer can be new to AWS; an AWS-certified learner can still need guidance in production work.</p><h2 id="certification-alignment" tabindex="-1">Certification alignment <a class="header-anchor" href="#certification-alignment" aria-label="Permalink to “Certification alignment”">​</a></h2><p><strong>Cloud Practitioner</strong> validates broad cloud understanding. This path goes deeper in application implementation, but exam preparation also needs coverage of business value, compliance, support, billing and the Well-Architected perspective. See the <a href="https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/" target="_blank" rel="noreferrer">official Cloud Practitioner guide</a>.</p><p><strong>Developer – Associate</strong> is the closest technical target. Development, security, testing/deployment and troubleshooting overlap strongly with these chapters. Compare the official guide for your intended exam version against what you can actually explain. Use official sample questions and current practice assessments to expose gaps; completing these notes alone is not an exam-readiness guarantee. Check the <a href="https://aws.amazon.com/certification/certified-developer-associate/" target="_blank" rel="noreferrer">current certification page</a> for version transitions before choosing preparation materials.</p><p><strong>Solutions Architect – Associate</strong> has substantial service overlap but a different architectural emphasis. These notes are a foundation, not a complete architecture-exam curriculum. Certification is not equivalent to professional seniority, and Cloud Practitioner is not a required prerequisite for learning this developer path.</p><h2 id="original-course-references" tabindex="-1">Original course references <a class="header-anchor" href="#original-course-references" aria-label="Permalink to “Original course references”">​</a></h2><ul><li><a href="https://ebook.learn.epam.com/cloudx-aws/docs/intro" target="_blank" rel="noreferrer">CloudX: AWS Practitioner for JS</a></li><li><a href="https://ebook.learn.epam.com/cloudx-associate-aws-js/docs/1.0.0/intro" target="_blank" rel="noreferrer">CloudX Associate: AWS JavaScript Developer</a></li></ul><p>These course sites may require organizational access. The user-supplied extracts are the course evidence for this version; official AWS documentation is the reference for changing platform behavior. Each chapter links its relevant service documentation.</p>',19)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
